3: import * as React from 'react';
4: import { Bee, Butterfly, Ladybug } from '@/components/nature/insects';
5: import { blades, r1 } from '@/components/nature/grass';
6: import { cn } from '@/lib/utils';
7: 
8: /**
9:  * The signature at the foot of the landing page: "Zephyrxx0" in the heaviest
10:  * Fraunces, planted in grass. One vine climbs out of the ground, weaves over and
11:  * under the letters (the segments alternate between a layer behind the text and
12:  * a layer in front of it) and finishes back in the soil. Blooms open along it,
13:  * flowers grow from the meadow, and bees, butterflies and ladybugs work the lot.
14:  *
15:  * Everything sits in one 1000 x 300 box so the drawing and the lettering scale
16:  * together. The glyph positions were measured from the rendered font; if the
17:  * wordmark's font, size or text changes, re-measure (see WORD below).
18:  *
19:  * It is the colour-inverse of the app: ink ground with paper-coloured lettering in
20:  * light mode, paper ground with ink lettering in dark mode (bg-foreground / text-background).
21:  * On inner pages it paints over the fixed side vines (z-10 above their z-0), which is
22:  * where those vines end.
23:  *
24:  * Motion: draws once when the footer scrolls into view, then idles with CSS
25:  * only. Under prefers-reduced-motion it simply appears, at rest.
26:  */
27: 
28: const W = 1000;
29: const H = 300;
30: const GROUND = 297;
31: 
32: /** Measured with getExtentOfChar at fontSize 190, weight 900, SOFT 100, opsz 144. */
33: const WORD = { text: 'Zephyrxx0', x: 500, y: 230, size: 190, length: 928.9 };
34: 
35: type Pt = [number, number];
36: type Seg = { a: Pt; c1: Pt; c2: Pt; b: Pt; front: boolean };
37: 
38: /** S-curve from a to b with level tangents at both ends, so joins are smooth. */
39: function wave(a: Pt, b: Pt, front: boolean, k = 0.5): Seg {
40:   const dx = (b[0] - a[0]) * k;
41:   return { a, c1: [a[0] + dx, a[1]], c2: [b[0] - dx, b[1]], b, front };
42: }
43: 
44: /**
45:  * Crests sit above the lowercase letters and troughs below the baseline, which is
46:  * open air. Segments can therefore swap between "in front" and "behind" at those
47:  * points without the vine ever visibly snapping.
48:  */
49: const PEAKS_AND_TROUGHS: Pt[] = [
50:   [93, 62],
51:   [196, 262],
52:   [296, 112],
53:   [400, 264],
54:   [504, 110],
55:   [596, 262],
56:   [690, 112],
57:   [790, 262],
58:   [890, 72],
59: ];
60: 
61: const SEGS: Seg[] = [
62:   { a: [12, GROUND + 4], c1: [4, 190], c2: [34, 62], b: PEAKS_AND_TROUGHS[0], front: true },
63:   wave(PEAKS_AND_TROUGHS[0], PEAKS_AND_TROUGHS[1], true),
64:   wave(PEAKS_AND_TROUGHS[1], PEAKS_AND_TROUGHS[2], false),
65:   wave(PEAKS_AND_TROUGHS[2], PEAKS_AND_TROUGHS[3], true),
66:   wave(PEAKS_AND_TROUGHS[3], PEAKS_AND_TROUGHS[4], false),
67:   wave(PEAKS_AND_TROUGHS[4], PEAKS_AND_TROUGHS[5], true),
68:   wave(PEAKS_AND_TROUGHS[5], PEAKS_AND_TROUGHS[6], false),
69:   wave(PEAKS_AND_TROUGHS[6], PEAKS_AND_TROUGHS[7], true),
70:   wave(PEAKS_AND_TROUGHS[7], PEAKS_AND_TROUGHS[8], false),
71:   { a: PEAKS_AND_TROUGHS[8], c1: [940, 72], c2: [992, 160], b: [988, GROUND + 4], front: true },
72: ];
73: 
74: const SEG_STEP = 0.36;
75: const SEG_START = 0.15;
76: const segDelay = (i: number) => SEG_START + i * SEG_STEP;
77: 
78: const pathOf = (s: Seg) => `M${s.a[0]} ${s.a[1]} C${r1(s.c1[0])} ${r1(s.c1[1])} ${r1(s.c2[0])} ${r1(s.c2[1])} ${s.b[0]} ${s.b[1]}`;
79: 
80: /** Point and heading (degrees) on a cubic Bezier at t. */
81: function onSeg(s: Seg, t: number) {
82:   const u = 1 - t;
83:   const x = u * u * u * s.a[0] + 3 * u * u * t * s.c1[0] + 3 * u * t * t * s.c2[0] + t * t * t * s.b[0];
84:   const y = u * u * u * s.a[1] + 3 * u * u * t * s.c1[1] + 3 * u * t * t * s.c2[1] + t * t * t * s.b[1];
85:   const dx = 3 * u * u * (s.c1[0] - s.a[0]) + 6 * u * t * (s.c2[0] - s.c1[0]) + 3 * t * t * (s.b[0] - s.c2[0]);
86:   const dy = 3 * u * u * (s.c1[1] - s.a[1]) + 6 * u * t * (s.c2[1] - s.c1[1]) + 3 * t * t * (s.b[1] - s.c2[1]);
87:   return { x: r1(x), y: r1(y), deg: r1((Math.atan2(dy, dx) * 180) / Math.PI) };
88: }
89: 
90: const LEAF = 'M0 0 C-7 -6 -7 -17 0 -24 C7 -17 7 -6 0 0 Z';
91: 
92: type LeafSpec = { seg: number; x: number; y: number; rot: number; scale: number; delay: number; dur: number; sway: number };
93: 
94: const LEAVES: LeafSpec[] = SEGS.flatMap((s, si) => {
95:   const ts = si === 0 || si === SEGS.length - 1 ? [0.2, 0.4, 0.6, 0.8] : [0.17, 0.38, 0.6, 0.82];
96:   return ts.map((t, k) => {
97:     const p = onSeg(s, t);
98:     const side = (si + k) % 2 === 0 ? 1 : -1;
99:     return {
100:       seg: si,
101:       x: p.x,
102:       y: p.y,
103:       rot: r1(p.deg + 90 + side * 52),
104:       scale: r1(0.8 + ((si * 3 + k * 5) % 5) * 0.09),
105:       delay: r1(segDelay(si) + 0.18 + k * 0.1),
106:       dur: r1(3.2 + ((si + k) % 4) * 0.7),
107:       sway: 5 + ((si * 2 + k) % 3) * 2,
108:     };
109:   });
110: });
111: 
112: /** Small curling tendrils: [x, y, flip, segment index it grows with]. */
113: const TENDRILS: Array<[number, number, 1 | -1, number]> = [
114:   [93, 62, 1, 0],
115:   [296, 112, -1, 2],
116:   [504, 110, 1, 4],
117:   [690, 112, -1, 6],
118:   [890, 72, 1, 8],
119:   [400, 264, -1, 3],
120:   [790, 262, 1, 7],
121: ];
122: const TENDRIL = 'M0 0 C8 -4 18 -2 19 7 C20 15 11 18 7 13 C4 9 8 6 11 8';
123: 
124: // ---------------------------------------------------------------------------
125: // Blooms
126: // ---------------------------------------------------------------------------
127: 
128: type BloomKind = 'daisy' | 'poppy' | 'cup' | 'cluster' | 'aster';
129: 
130: /** Fill for each hue; poppies burn warm, the rest use the pastel meadow palette. */
131: const fillFor = (kind: BloomKind, hue: number) => `var(--${kind === 'poppy' ? 'heat' : 'bloom'}-${hue})`;
132: const CENTER = (kind: BloomKind) => (kind === 'poppy' ? 'oklch(0.27 0.03 80)' : 'var(--bloom-center)');
133: 
134: /** A bloom face centred on the origin; r is roughly its radius in box units. */
135: function Bloom({ kind, hue, r }: { kind: BloomKind; hue: number; r: number }) {
136:   const k = r / 12;
137:   const fill = { fill: fillFor(kind, hue) };
138:   const ink = 'stroke-background/45';
139:   return (
140:     <g transform={`scale(${r1(k)})`} style={fill} className={ink} strokeWidth={0.8 / k}>
141:       {kind === 'daisy' &&
142:         Array.from({ length: 10 }, (_, i) => <ellipse key={i} cx="0" cy="-7" rx="3.1" ry="7.4" transform={`rotate(${i * 36})`} />)}
143:       {kind === 'aster' &&
144:         Array.from({ length: 5 }, (_, i) => <ellipse key={i} cx="0" cy="-6" rx="4.6" ry="6.6" transform={`rotate(${i * 72})`} />)}
145:       {kind === 'poppy' &&
146:         Array.from({ length: 5 }, (_, i) => <ellipse key={i} cx="0" cy="-6.4" rx="6.4" ry="7.2" transform={`rotate(${i * 72 + 20})`} />)}
147:       {kind === 'cluster' && (
148:         <>
149:           <circle cx="0" cy="-5" r="6" />
150:           <circle cx="-7" cy="3" r="5.4" />
151:           <circle cx="7" cy="3" r="5.4" />
152:         </>
153:       )}
154:       {kind === 'cup' && (
155:         <>
156:           <path d="M-9 -8 C-9 4 -5 10 0 10 C5 10 9 4 9 -8 L4.5 -3 L0 -12 L-4.5 -3 Z" />
157:           <path d="M0 -12 C-3 -4 -3 4 0 10 C3 4 3 -4 0 -12 Z" className="opacity-60" />
158:         </>
159:       )}
160:       {kind !== 'cup' && kind !== 'cluster' && <circle cx="0" cy="0" r={kind === 'poppy' ? 3.4 : 3.8} style={{ fill: CENTER(kind) }} />}
161:       {kind === 'cluster' && <circle cx="0" cy="-1" r="2" style={{ fill: CENTER(kind) }} stroke="none" />}
162:     </g>
163:   );
164: }
165: 
166: type Blossom = { x: number; y: number; kind: BloomKind; hue: number; r: number; delay: number };
167: 
168: /** Bloom on every crest and trough of the vine, bigger up top, smaller where the grass hides them. */
169: const BLOSSOMS: Blossom[] = PEAKS_AND_TROUGHS.map(([x, y], i) => {
170:   const kinds: BloomKind[] = ['poppy', 'aster', 'daisy', 'cluster', 'poppy', 'aster', 'daisy', 'cluster', 'poppy'];
171:   const up = y < 150;
172:   return { x, y, kind: kinds[i], hue: (i % 4) + 1, r: up ? 19 : 13, delay: r1(segDelay(i) + 0.3) };
173: });
174: 
175: type Stalk = { x: number; h: number; kind: BloomKind; hue: number; lean: number; deg: number; dur: number; delay: number };
176: 
177: const STALK_SPECS: Array<[number, number, BloomKind, number]> = [
178:   [62, 74, 'daisy', 1],
179:   [128, 46, 'cluster', 3],
180:   [172, 96, 'poppy', 2],
181:   [226, 58, 'cup', 4],
182:   [318, 86, 'cluster', 2],
183:   [372, 50, 'daisy', 3],
184:   [436, 98, 'poppy', 1],
185:   [486, 62, 'cup', 2],
186:   [580, 90, 'daisy', 4],
187:   [632, 52, 'cluster', 1],
188:   [702, 96, 'cup', 3],
189:   [760, 58, 'poppy', 4],
190:   [818, 88, 'daisy', 2],
191:   [868, 54, 'cluster', 3],
192:   [934, 92, 'poppy', 1],
193:   [966, 60, 'cup', 2],
194: ];
195: 
196: const STALKS: Stalk[] = STALK_SPECS.map(([x, h, kind, hue], i) => ({
197:   x,
198:   h,
199:   kind,
200:   hue,
201:   lean: ((i * 7) % 5) - 2,
202:   deg: r1(2 + (i % 3) * 0.7),
203:   dur: r1(4.2 + (i % 5) * 0.55),
204:   delay: r1(1.4 + i * 0.1),
205: }));
206: 
207: const GRASS = [
208:   { d: blades(11, 190, 38, 0, false), opacity: 0.5, dur: 8, delay: -2 },
209:   { d: blades(23, 230, 30, 0, false), opacity: 0.85, dur: 6.5, delay: -4 },
210: ];
211: 
212: // ---------------------------------------------------------------------------
213: // Insects. HTML, positioned in the same 1000 x 300 space as percentages, and
214: // sized in container units so they scale with the lettering.
215: // ---------------------------------------------------------------------------
216: 
217: const px = (x: number) => `${r1(x / 10)}%`;
218: const py = (y: number) => `${r1((y / H) * 100)}%`;
219: const size = (cqw: number, min: number) => `max(${min}px, ${cqw}cqw)`;
220: 
221: const BEES = [
222:   { x: 93, y: 62, dur: 9, delay: -2, r: 1.2 },
223:   { x: 504, y: 110, dur: 11, delay: -6, r: 1.3 },
224:   { x: 890, y: 72, dur: 10, delay: -4, r: 1.2 },
225:   { x: 436, y: 200, dur: 8.5, delay: -1, r: 1 },
226: ];
227: 
228: const FLITTERS = [
229:   { x: 296, y: 100, color: 'var(--bloom-3)', dur: 15, delay: -3, bob: 3.6, w: 3.4 },
230:   { x: 690, y: 98, color: 'var(--heat-3)', dur: 17, delay: -8, bob: 4.1, w: 3.6 },
231:   { x: 150, y: 150, color: 'var(--bloom-1)', dur: 19, delay: -12, bob: 3.9, w: 2.8 },
232: ];
233: 
234: /** Ladybugs walk along the tops of letters: x and y are the top of the spot they stand on. */
235: const LADYBUGS = [
236:   { x: 52, y: 95, dist: 6.2, dur: 17, delay: -3 }, // across the top bar of the Z
237:   { x: 648, y: 142, dist: 4.8, dur: 14, delay: -7 }, // along the first x
238:   { x: 562, y: 142, dist: 2.2, dur: 11, delay: -1 }, // on the r
239: ];
240: 
241: export function SignatureFooter({ className }: { className?: string }) {
242:   const ref = React.useRef<HTMLElement>(null);
243:   const [seen, setSeen] = React.useState(false);
244: 
245:   React.useEffect(() => {
246:     const el = ref.current;
247:     if (!el) return;
248:     const io = new IntersectionObserver(
249:       ([entry]) => {
250:         if (entry.isIntersecting) {
251:           setSeen(true);
252:           io.disconnect();
253:         }
254:       },
255:       { threshold: 0.3 },
256:     );
257:     io.observe(el);
258:     return () => io.disconnect();
259:   }, []);
260: 
261:   const back = SEGS.map((s, i) => ({ s, i })).filter(({ s }) => !s.front);
262:   const front = SEGS.map((s, i) => ({ s, i })).filter(({ s }) => s.front);
263: 
264:   const leafGroup = (ls: LeafSpec[]) =>
265:     ls.map((l, i) => (
266:       <g key={i} transform={`translate(${l.x} ${l.y}) rotate(${l.rot}) scale(${l.scale})`}>
267:         <g className="sig-pop" style={{ ['--delay' as string]: `${l.delay}s` }}>
268:           <g
269:             className="nature-sway"
270:             style={{ ['--deg' as string]: `${l.sway}deg`, ['--dur' as string]: `${l.dur}s`, ['--delay' as string]: `${-i * 0.7}s` }}
271:           >
272:             <path d={LEAF} fill="var(--vine-leaf)" stroke="var(--vine-leaf-edge)" strokeWidth="1.3" />
273:             <path d="M0 -1 V-20" stroke="var(--vine-leaf-edge)" strokeWidth="1" opacity="0.7" />
274:           </g>
275:         </g>
276:       </g>
277:     ));
278: 
279:   return (
280:     <footer ref={ref} className={cn('relative z-10 w-full select-none overflow-hidden bg-foreground pt-8 text-background sm:pt-14', className)}>
281:       <div
282:         data-in={seen ? '' : undefined}
283:         className="sig relative mx-auto w-full max-w-[1500px] [container-type:inline-size]"
284:         style={{ aspectRatio: `${W} / ${H}` }}
285:       >
286:         <svg
287:           viewBox={`0 0 ${W} ${H}`}
288:           className="absolute inset-0 h-full w-full overflow-visible"
289:           role="img"
290:           aria-label="Zephyrxx0"
291:           fill="none"
292:           strokeLinecap="round"
293:           strokeLinejoin="round"
294:         >
295:           {/* 1. vine behind the letters */}
296:           <g>
297:             {back.map(({ s, i }) => (
298:               <path
299:                 key={i}
300:                 d={pathOf(s)}
301:                 pathLength={1}
302:                 className="sig-draw"
303:                 stroke="var(--vine)"
304:                 strokeWidth="4.4"
305:                 style={{ ['--delay' as string]: `${segDelay(i)}s` }}
306:               />
307:             ))}
308:             {leafGroup(LEAVES.filter((l) => !SEGS[l.seg].front))}
309:           </g>
310: 
311:           {/* 2. the wordmark */}
312:           <text
313:             x={WORD.x}
314:             y={WORD.y}
315:             textAnchor="middle"
316:             fontSize={WORD.size}
317:             textLength={WORD.length}
318:             lengthAdjust="spacingAndGlyphs"
319:             className="fill-background font-serif font-black"
320:             style={{ fontVariationSettings: '"SOFT" 100, "opsz" 144', fontVariantNumeric: 'lining-nums' }}
321:           >
322:             {WORD.text}
323:           </text>
324: 
325:           {/* 3. vine in front of the letters, with a thin halo of page colour so it reads on the ink */}
326:           <g>
327:             {front.map(({ s, i }) => (
328:               <g key={i} style={{ ['--delay' as string]: `${segDelay(i)}s` }}>
329:                 <path d={pathOf(s)} pathLength={1} className="sig-draw" stroke="var(--foreground)" strokeWidth="10" />
330:                 <path d={pathOf(s)} pathLength={1} className="sig-draw" stroke="var(--vine)" strokeWidth="4.4" />
331:               </g>
332:             ))}
333:             {leafGroup(LEAVES.filter((l) => SEGS[l.seg].front))}
334:           </g>
335: 
336:           {/* tendrils */}
337:           {TENDRILS.map(([x, y, flip, si], i) => (
338:             <g key={i} transform={`translate(${x} ${y}) scale(${flip} 1)`}>
339:               <path
340:                 d={TENDRIL}
341:                 pathLength={1}
342:                 className="sig-draw"
343:                 stroke="var(--vine)"
344:                 strokeWidth="2.4"
345:                 style={{ ['--delay' as string]: `${segDelay(si) + 0.35}s`, ['--len' as string]: '0.7s' }}
346:               />
347:             </g>
348:           ))}
349: 
350:           {/* 4. blooms on the vine */}
351:           {BLOSSOMS.map((b, i) => (
352:             <g key={i} transform={`translate(${b.x} ${b.y})`}>
353:               <g className="sig-pop-c" style={{ ['--delay' as string]: `${b.delay}s` }}>
354:                 <g className="nature-sway" style={{ ['--deg' as string]: '5deg', ['--dur' as string]: `${4 + (i % 4) * 0.6}s`, ['--delay' as string]: `${-i}s` }}>
355:                   <Bloom kind={b.kind} hue={b.hue} r={b.r} />
356:                 </g>
357:               </g>
358:             </g>
359:           ))}
360: 
361:           {/* 5. the meadow it all grows from */}
362:           <g transform={`translate(0 ${GROUND}) scale(${r1(W / 1200)})`}>
363:             {GRASS.map((g, i) => (
364:               <g key={i} className="nature-grass" style={{ ['--dur' as string]: `${g.dur}s`, ['--delay' as string]: `${g.delay}s` }}>
365:                 <path d={g.d} stroke="var(--vine)" strokeOpacity={g.opacity} strokeWidth="1.7" />
366:               </g>
367:             ))}
368:           </g>
369: 
370:           {STALKS.map((f, i) => {
371:             const topY = GROUND - f.h;
372:             const tx = f.x + f.lean * 2;
373:             return (
374:               <g key={i} transform={`translate(${f.x} ${GROUND})`} className={i % 2 ? 'max-sm:hidden' : undefined}>
375:                 <g className="sig-pop" style={{ ['--delay' as string]: `${f.delay}s` }}>
376:                   <g className="nature-sway" style={{ ['--deg' as string]: `${f.deg}deg`, ['--dur' as string]: `${f.dur}s`, ['--delay' as string]: `${-i * 0.9}s` }}>
377:                     <path
378:                       d={`M0 0 C${f.lean * 2} ${-f.h * 0.35} ${f.lean * 3} ${-f.h * 0.7} ${tx - f.x} ${-f.h + 8}`}
379:                       stroke="var(--vine)"
380:                       strokeWidth="2.6"
381:                     />
382:                     <path d={`M${f.lean} ${-f.h * 0.3} c-10 -2 -16 -8 -16 -14 c8 0 14 5 16 14 Z`} fill="var(--vine-leaf)" stroke="var(--vine-leaf-edge)" strokeWidth="1" />
383:                     <path d={`M${f.lean * 2} ${-f.h * 0.5} c10 -2 16 -8 16 -14 c-8 0 -14 5 -16 14 Z`} fill="var(--vine-leaf)" stroke="var(--vine-leaf-edge)" strokeWidth="1" />
384:                     <g transform={`translate(${tx - f.x} ${topY - GROUND})`}>
385:                       <Bloom kind={f.kind} hue={f.hue} r={11 + (i % 3) * 2} />
386:                     </g>
387:                   </g>
388:                 </g>
389:               </g>
390:             );
391:           })}
392: 
393:           <path d={`M0 ${GROUND + 0.5} H${W}`} className="stroke-background/30" strokeWidth="1" />
394:         </svg>
395: 
396:         {/* life: decorative, never in the way */}
397:         <div aria-hidden="true" className="sig-fade pointer-events-none absolute inset-0" style={{ ['--delay' as string]: '1.8s' }}>
398:           {FLITTERS.map((b, i) => (
399:             <div key={i} className={i === 2 ? 'absolute max-sm:hidden' : 'absolute'} style={{ left: px(b.x), top: py(b.y) }}>
400:               <div className="nature-wander" style={{ ['--dur' as string]: `${b.dur}s`, ['--delay' as string]: `${b.delay}s`, ['--r' as string]: 2.4 }}>
401:                 <div className="nature-bob" style={{ ['--bob' as string]: `${b.bob}s` }}>
402:                   <Butterfly color={b.color} className="-translate-x-1/2 -translate-y-1/2" style={{ width: size(b.w, 22), height: size(b.w * 0.875, 19) }} />
403:                 </div>
404:               </div>
405:             </div>
406:           ))}
407: 
408:           <div className="nature-cross absolute left-0" style={{ top: py(40), ['--dur' as string]: '58s', ['--delay' as string]: '-20s' }}>
409:             <div className="nature-bob" style={{ ['--bob' as string]: '4.4s' }}>
410:               <Butterfly color="var(--heat-4)" style={{ width: size(3, 20), height: size(2.6, 17) }} />
411:             </div>
412:           </div>
413: 
414:           {BEES.map((b, i) => (
