const TOTAL_FRAMES = 185; // up to peak bloom
const pingPongCmd = `ffmpeg -y -framerate ${growthFps} -start_number ${START_FRAME} -i "${FRAMES_DIR_GROWTH}/frame_%05d.png" -vframes ${TOTAL_FRAMES} -filter_complex "[0:v] fps=30,split [fwd][for_rev];[for_rev] reverse [rev];[fwd][rev] concat=n=2:v=1 [both];[both] split [p1][p2];[p1] palettegen=stats_mode=diff [pal];[p2][pal] paletteuse=dither=bayer:bayer_scale=3:diff_mode=rectangle" -loop 0 "${pingPongGifPath}"`;
execSync(pingPongCmd, { stdio: 'inherit' });

// Also update main treads.gif and treads-animation.gif with this tight growth loop
execSync(`cp "${pingPongGifPath}" "${join(outputDir, 'treads.gif')}"`);
execSync(`cp "${pingPongGifPath}" "${join(outputDir, 'treads-animation.gif')}"`);
console.log('Updated public/treads.gif and public/treads-animation.gif!');

